@extends('layouts.app') @section('title','User Management') @section('content')<div class="card"><div class="card-header d-flex justify-content-between"><strong>System Users</strong><a href="{{ route('users.create') }}" class="btn btn-primary">Add User</a></div><table class="table mb-0"><thead><tr><th>Name</th><th>Contact</th><th>Role</th><th>Status</th><th>Created</th><th></th></tr></thead><tbody>@foreach($users as $u)<tr><td><strong>{{ $u->name }}</strong></td><td>{{ $u->email }}<br><small>{{ $u->phone ?: 'No phone' }}</small></td><td>{{ ucfirst($u->role) }}</td><td>{!! status_badge($u->status) !!}</td><td>{{ date('d M Y',strtotime($u->created_at)) }}</td><td><form method="post" action="{{ route('users.status',$u->id) }}">@csrf @method('PATCH')<input type="hidden" name="status" value="{{ $u->status==='active'?'inactive':'active' }}"><button class="btn btn-sm btn-light" @disabled($u->id==current_user()['id'])>{{ $u->status==='active'?'Deactivate':'Activate' }}</button></form></td></tr>@endforeach</tbody></table></div>@endsection
